Given a Directed Acyclic Graph(DAG), find any Topological Sorted order of the graph.Topological Sorted order: It is a linear ordering of vertices such that for every directed edge u -> v, where vertex u comes before v in the ordering.There can be several topological ordering for a graph.Example:Input: adj[][]= [[1], [], [1], [2], [2]] Output: [4, 3, 2, 0, 1] Explanation: By following that: for an edge u->v, u must come before v, we can obtain several topological orderings and [4, 3, 2, 0, 1] is one of them.Input: V=5 , adj[][] = [[1], [2], [], [2, 4], []] Output: [0, 3, 1, 4, 2]Explanation: By following that: for an edge u->v, u must come before v, we can obtain several topological orderings and [0, 3, 1, 4, 2] is one of them.[Approach]The idea is to perform a DFS traversal starting from every unvisited vertex (from 0 to n − 1). For each DFS call, we first explore all unvisited neighbors of the current node. Once the recursive calls for all its neighbors are complete, we start pushing these nodes into a stack while backtracking. After all vertices are processed, we pop elements from the stack one by one into a list — this gives a valid topological ordering, as each node is placed before all nodes it points to.Illustration of the algorithm:Below is the implementation of the above algorithm. 
            C++

    //Driver Code Starts
#include <iostream>
#include <vector>
#include <stack>
using namespace std;

//Driver Code Ends

void findTopoSort(int node, vector<int>& vis, vector<vector<int>>& adj, stack<int>& st) {
    vis[node] = 1;
    for (int it : adj[node]) {
        if (!vis[it]) {
            findTopoSort(it, vis, adj, st);
        }
    }
    // push the node after all its neighbours
    st.push(node);
}

vector<int> topoSort(vector<vector<int>>& adj) {
    int n = adj.size();
    stack<int> st;
    vector<int> vis(n, 0);

    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            findTopoSort(i, vis, adj, st);
        }
    }
    vector<int> topo;

    // popping elements from stack and 
    // pushing into the list
    while (!st.empty()) {
        topo.push_back(st.top());
        st.pop();
    }
    return topo;
}

//Driver Code Starts

void addEdge(vector<vector<int>>& adj, int u, int v) {
    adj[u].push_back(v);
}

int main() {
    int n = 5;
    vector<vector<int>> adj(n);

    // adding edges to adjacency list
    addEdge(adj, 0, 1);
    addEdge(adj, 2, 1);
    addEdge(adj, 3, 2);
    addEdge(adj, 4, 2);

    vector<int> res = topoSort(adj);
    for (int vertex : res)
        cout << vertex << " ";
    cout << endl;
}

