    //Driver Code Starts
import java.util.ArrayList;
import java.util.Stack;

class Solution {
//Driver Code Ends

    static void findTopoSort(int node, int[] vis, ArrayList<ArrayList<Integer>> adj, Stack<Integer> st) {
        vis[node] = 1;
        for (Integer it : adj.get(node)) {
            if (vis[it] == 0) {
                findTopoSort(it, vis, adj, st);
            }
        }
        // Push the node after visiting 
        // all its neighbours
        st.push(node);
    }

    static ArrayList<Integer> topoSort(ArrayList<ArrayList<Integer>> adj) {
        int n = adj.size();
        Stack<Integer> st = new Stack<>();
        int[] vis = new int[n];

        for (int i = 0; i < n; i++) {
            if (vis[i] == 0) {
                findTopoSort(i, vis, adj, st);
            }
        }

        ArrayList<Integer> topo = new ArrayList<>();

        // popping elements from stack and 
        // pushing into the list
        while (!st.isEmpty()) {
            topo.add(st.pop());
        }
        return topo;
    }

//Driver Code Starts

    static void addEdge(ArrayList<ArrayList<Integer>> adj, int u, int v) {
        adj.get(u).add(v);
    }

    public static void main(String[] args) {
        int n = 5; 
        ArrayList<ArrayList<Integer>> adj = new ArrayList<>();

        for (int i = 0; i < n; i++)
            adj.add(new ArrayList<>());


        // adding edges to adjacency list
        addEdge(adj, 0, 1);
        addEdge(adj, 2, 1);
        addEdge(adj, 3, 2);
        addEdge(adj, 4, 2);

        ArrayList<Integer> res = topoSort(adj);

        for (int vertex : res) {
            System.out.print(vertex + " ");
        }
        System.out.println();
    }
}

